Lemma bytes_at_copy (M1 M2 : word -> option byte) src dst l :
  (forall i, 0 <= i < Z.of_nat (length l) -> M2 (Z_to_bv 64 (dst + i)) = M1 (Z_to_bv 64 (src + i))) ->
